/*
 *   @param  {string} fieldType - Feldtyp, dessen Row-Index in der Fixture ermittelt wird
 */
export async function downloadAndCompareFieldRules({
  page,
  fixture,
  fieldType,
  expectedRules,
  dialogDefaultName = 'formular.json',
}: {
  page: Page;
  fixture: object;
  fieldType?: string;
  expectedRules: object[];
  dialogDefaultName?: string;
}) {
  const dialogHandler = async (dialog: Dialog) => {
    await dialog.accept(dialogDefaultName);
  };

  page.once('dialog', dialogHandler);

  const downloadPromise = page.waitForEvent('download', { timeout: 5000 });
  await page.getByRole('button', { name: 'JSON herunterladen' }).click();

  const download = await downloadPromise;

  let downloadedJson: any;
  try {
    const stream = await download.createReadStream();
    const chunks: Buffer[] = [];
    for await (const chunk of stream) {
      chunks.push(Buffer.from(chunk));
    }
    downloadedJson = JSON.parse(Buffer.concat(chunks).toString('utf-8'));
  } catch (error) {
    throw new Error(
      `Failed to parse downloaded file as JSON: ${error instanceof Error ? error.message : String(error)}`,
    );
  }

  const index = fieldType ? getFieldRowIndex(fixture, fieldType) : 0;
  const field = downloadedJson.sections[0].fieldGroups[0].rows[index].fields[0];
  expect(field.validationRules).toEqual(expectedRules);
}

